-- Merge duplicate fardo variants: same product name + same calidad/kilo, but two
-- different barcodes on record (mostly from historical duplicate product rows, e.g. an
-- English-named product and its Spanish counterpart that were later renamed to the same
-- name without merging). For each such pair, keep the barcode the SARDES BALYA (fardo)
-- list says is correct, fold the other variant into it, and sum per-branch stock so on-hand
-- quantities don't change. The old (wrong/duplicate) barcode is kept as an extra alias in
-- variant_barcodes, so a fardo still wearing the old sticker still scans to the right product.
-- One conflict (PANTALON MUJER VERANO / PANTALON JUVENIL VERANO, both claiming 869001333028)
-- is intentionally excluded -- it needs a human call, not folded in here.
--
-- Two of the retired (loser) barcodes here (869001333028 and 8690025040451) are also
-- involved in separate, still-open barcode disputes reported earlier (which product they
-- really belong to hasn't been confirmed). They're excluded from the alias step below so
-- this merge doesn't quietly decide those open questions -- they stay fully unclaimed.
create temporary table _merge_map (
  survivor_id uuid, loser_id uuid, target_sku text, survivor_old_sku text, loser_old_sku text
) on commit drop;


update public.sale_items si set variant_id = m.survivor_id
from _merge_map m where si.variant_id = m.loser_id;

update public.container_items ci set variant_id = m.survivor_id
from _merge_map m where ci.variant_id = m.loser_id;

update public.inventory_movements im set variant_id = m.survivor_id
from _merge_map m where im.variant_id = m.loser_id;

update public.variant_barcodes vb set variant_id = m.survivor_id
from _merge_map m where vb.variant_id = m.loser_id;

select m.survivor_id, i.branch_id, i.quantity
from public.inventory i join _merge_map m on i.variant_id = m.loser_id
on conflict (variant_id, branch_id) do update
set quantity = public.inventory.quantity + excluded.quantity, updated_at = now();

delete from public.inventory where variant_id in (select loser_id from _merge_map);

update public.product_variants set sku = null, updated_at = now()
where id in (select loser_id from _merge_map);

update public.product_variants v set sku = m.target_sku, updated_at = now()
from _merge_map m where v.id = m.survivor_id and v.sku is distinct from m.target_sku;

update public.product_variants v
set active = false, deleted_at = now(),
    delete_reason = 'Fusionado con variante duplicada (mismo producto/calidad, barcode distinto); barcode correcto = ' || m.target_sku
from _merge_map m where v.id = m.loser_id;

select m.survivor_id, code
from _merge_map m, unnest(array[m.loser_old_sku, m.survivor_old_sku]) as code
where code is not null
  and upper(regexp_replace(code, '[[:space:]-]', '', 'g')) <> upper(regexp_replace(m.target_sku, '[[:space:]-]', '', 'g'))
  and upper(regexp_replace(code, '[[:space:]-]', '', 'g')) not in ('869001333028', '8690025040451')
on conflict (code_normalized) do nothing;
